<template>
  <el-dialog
    :title="title"
    :visible.sync="dialogFormVisible"
    v-if="dialogFormVisible"
    @destroy-on-close="true"
    width="760px"
    top="1vh"
  >
    <div v-if="type === 'default'">
      <div class="point-tip">
        <strong>中心点位坐标：</strong>
        <el-input v-model="form.x" size="mini" class="point-input"
          ><template slot="prepend">x</template></el-input
        >
        <el-input v-model="form.y" size="mini" class="point-input"
          ><template slot="prepend">y</template></el-input
        >
      </div>
      <div class="electronic-map-add-marker-map" ref="electronicMapBaseMap">
        <div class="img-box" ref="electronicMapBaseMapImg"></div>
        <point-marker-tool
          ref="pointMarkerTool2"
          :backgroundImage="url"
          :limit="1"
          v-if="url"
          :maxWidth="760"
          @marker-added="onNodeMarker"
          @marker-removed="onRemoveNodeMarker"
        />
      </div>
    </div>
    <div v-if="type === 'gis'">
      <div class="gis-map" id="gis-map"></div>
    </div>
    <div slot="footer" class="dialog-footer">
      <el-button @click="onCancel">取 消</el-button>
      <el-button type="primary" @click="onSave">确 定</el-button>
    </div>
  </el-dialog>
</template>
    
<script>
import { getGisTilesImageUrl } from '@/api/iot'
import { getProductScenes } from '@/api/vr'
// eslint-disable-next-line no-unused-vars
import * as L from 'leaflet'
import 'leaflet-draw'
import '@/plugins/LeafletDrawCn'
// eslint-disable-next-line no-unused-vars
const defaultForm = {
  x: 0,
  y: 0,
  sceneMarkers: [],
}
export default {
  name: 'MapCenterPointConfig',
  components: {
    PointMarkerTool: () => import('@/components/point-marker-tool'),
  },
  data() {
    return {
      url: '',
      dialogFormVisible: false,
      form: Object.assign({}, defaultForm),
      sceneId: null,
      node: null,
      type: 'default',
      gisMap: null,
      sceneNodes: [],
      scenes: [],
      drawnItems: null,
    }
  },
  computed: {
    title() {
      return this.type === 'default'
        ? '设置全景图在电子地图上的中心点'
        : '设置全景图在GIS地图上的中心点'
    },
    noSelectScenes() {
      return this.scenes.filter(
        (item) =>
          this.sceneNodes.findIndex((node) => node.sceneId === item.id) < 0
      )
    },
  },
  props: {
    productId: null,
  },
  methods: {
    open(type, url, node, sceneNodes = []) {
      // console.log(type, url, node, sceneNodes)
      this.type = type
      this.url = url
      this.sceneNodes = sceneNodes
      this.dialogFormVisible = true
      if (node && node.position) {
        this.form.x = node.position.x
        this.form.y = node.position.y
        this.node = node
      }

      setTimeout(() => {
        if (type === 'default') {
          this.initMapBaseMapImage()
        } else if (type === 'gis') {
          this.initGisMap()
        }
      }, 200)
    },
    async getProductScenes() {
      this.scenes = await getProductScenes(this.productId)
    },
    // eslint-disable-next-line no-unused-vars
    onNodeMarker(node) {
      this.form.x = node.position.x
      this.form.y = node.position.y
      this.node = node
    },
    async initGisMap() {
      // eslint-disable-next-line no-unused-vars
      await this.getProductScenes()
      this.form.sceneMarkers = this.sceneNodes
      this.$nextTick(async () => {
        const tilesData = await getGisTilesImageUrl()
        this.gisMap = L.map('gis-map', {
          minZoom: parseFloat(tilesData.zoom_config.min),
          maxZoom: parseFloat(tilesData.zoom_config.max),
          zoomDelta: parseFloat(tilesData.zoom_config.zoom_delta),
          zoomSnap: parseFloat(tilesData.zoom_config.zoom_delta), //zoom_snap
          attributionControl: false,
          attribution: 'VR',
        }).setView(tilesData.center, parseFloat(tilesData.zoom_config.zoom))
        const layers = []
        const tilesUrlList = this.url.split('\n')
        tilesUrlList.forEach((item) => {
          layers.push(L.tileLayer(item, tilesData.tiles.options))
        })
        this.gisMap.addLayer(L.layerGroup(layers))
        // eslint-disable-next-line no-unused-vars

        const markerIcon = L.icon({
          iconUrl: require('leaflet-draw/dist/images/marker-icon.png'),
          iconSize: [25, 41],
          iconAnchor: [22, 94],
          popupAnchor: [-3, -76],
          shadowUrl: require('leaflet-draw/dist/images/marker-shadow.png'),
          shadowSize: [25, 41],
          shadowAnchor: [22, 94],
        })
        // eslint-disable-next-line no-unused-vars
        const drawColor = {
          line: '#ff3434',
          polygon: '#2bec9e',
          rectangle: '#42ebfa',
          circle: '#2819f2',
        }
        const drawnItems = new L.FeatureGroup()
        this.sceneNodes.forEach((node) => {
          const marker = L.marker(L.latLng(node.position.y, node.position.x), {
            icon: markerIcon,
          }).bindPopup(node.sceneTitle, {
            closeButton: false,
            closeOnClick: false,
            autoClose: false,
            className: 'scene-marker-label',
          })
          drawnItems.addLayer(marker)
          setTimeout(() => {
            marker.openPopup()
          }, 0)
        })
        const drawControl = new L.Control.Draw({
          position: 'topright',
          draw: {
            // polyline: {
            //   shapeOptions: {
            //     color: drawColor.line,
            //     weight: 10,
            //   },
            // },
            // polygon: {
            //   allowIntersection: false, // Restricts shapes to simple polygons
            //   drawError: {
            //     color: '#e1e100', // Color the shape will turn when intersects
            //     message: '<strong>绘制出错</strong>',
            //   },
            //   shapeOptions: {
            //     color: drawColor.polygon,
            //   },
            // },
            // circle: {
            //   shapeOptions: {
            //     color: drawColor.circle,
            //   },
            // },
            // rectangle: {
            //   shapeOptions: {
            //     color: drawColor.rectangle,
            //     clickable: false,
            //   },
            // },
            polyline: false,
            circle: false,
            polygon: false,
            rectangle: false,
            marker: {
              icon: markerIcon,
            },
            circlemarker: false,
          },
          edit: {
            featureGroup: drawnItems,
            remove: true,
          },
        })
        this.gisMap.addControl(drawControl)
        this.gisMap.addLayer(drawnItems)
        this.drawnItems = drawnItems
        this.gisMap.off(L.Draw.Event.CREATED).on(L.Draw.Event.CREATED, (e) => {
          // eslint-disable-next-line no-unused-vars
          const { layer } = e
          const scenes = this.noSelectScenes
          const currentScene = scenes.shift()
          if (!currentScene) {
            this.$message.warning('标记失败，没有更多场景了')
            return false
          }

          layer.bindPopup(currentScene.title, {
            closeButton: false,
            closeOnClick: false,
            autoClose: false,
            className: 'scene-marker-label',
          })
          drawnItems.addLayer(layer)
          this.form.sceneMarkers.push({
            sceneId: currentScene.id,
            sceneTitle: currentScene.title,
            position: {
              x: layer.getLatLng().lng,
              y: layer.getLatLng().lat,
            },
            scale: {
              scaleW: 1,
              scaleH: 1,
            }
          })
          layer.openPopup()
          // this.gisMap.addLayer(layer)
        })
        this.gisMap.on(L.Draw.Event.DELETED, (e) => {
          for (const layer in e.layers._layers) {
            const index = this.form.sceneMarkers.findIndex(
              (item) => item.position.x === layer.lng && item.position.y === layer.lat
            )
            this.form.sceneMarkers.splice(index, 1)
          }
        })
      })
    },
    initMapBaseMapImage() {
      this.$refs.pointMarkerTool2.enable()
      if (this.node) {
        this.$refs.pointMarkerTool2.setMarkers()
      }
    },
    onRemoveNodeMarker() {
      this.form = Object.assign({}, defaultForm)
      this.node = null
    },
    onCancel() {
      this.form = Object.assign({}, defaultForm)
      this.dialogFormVisible = false
      this.node = null
      if (this.gisMap) {
        this.drawnItems = null
        this.gisMap.off()
        this.gisMap.remove()
      }
    },
    onSave() {
      if (this.type === 'default') {
        this.$emit('updateMapPointConfig', this.type, this.node)
      } else if (this.type === 'gis') {
        this.$emit('updateMapPointConfig', this.type, this.form)
      }

      this.onCancel()
    },
  },
}
</script>
